def target_num(x):
    if x in (None, ""):
        return None
    try:
        f = float(str(x).replace(",", "").strip())
    except ValueError:
        raise ValueError(f"'{x}' is not a number.")
    if f < 0 or f != f or f == float("inf"):
        raise ValueError("Targets can't be negative.")
    return f


