# ════════════════════════════════════════════════════════════════════
#  DAY-WISE SALES: every day of a range, split by segment / SPC / model / store
# ════════════════════════════════════════════════════════════════════
DW_BY = {"none": None, "seg": "seg", "spc": "spc", "fam": "fam", "store": "store"}


def daywise_data(st, args):
    daily = daily_frame(st)
    if daily is None or daily.empty:
        return {"error": "This sheet has no usable date column."}
    stores = sorted(s for s in daily["store"].unique() if s)
    sel = pick_scope(args, stores)
    sp, ff = args.get("sp") == "1" if "sp" in args else group_pref("sp", False), args.get("ff", "1") == "1"
    d = seg_only(regroup(scope_rows(daily, sel), sp, ff), args)
    dmin, dmax = daily["day"].min(), daily["day"].max()
    a, b = parse_date(args.get("start")), parse_date(args.get("end"))
    b = dmax if b is None else min(b.normalize(), dmax)
    a = b.replace(day=1) if a is None else max(a.normalize(), dmin)
    if a > b:
        a = b
    if (b - a).days > 370:
        a = b - pd.Timedelta(days=370)
    by = args.get("by", "seg")
    col = DW_BY.get(by, "seg")
    cur = ov_slice(d, a, b)
    tot = d.groupby("day")[["v", "q"]].sum()
    cols, split = [], {}
    if col:
        g = cur[cur[col] != ""].groupby(col, observed=True)[["v", "q"]].sum().sort_values("v", ascending=False)
        limit = 12 if col in ("fam", "spc") else 20
        cols = [str(x) for x in g.index[:limit]]
        other = len(g) > limit
        gd = cur.groupby(["day", col], observed=True)[["v", "q"]].sum()
        for (day, name), r in gd.iterrows():
            key = str(name) if str(name) in cols else ("Others" if other and name != "" else None)
            if key is None:
                continue
            cell = split.setdefault(day, {}).setdefault(key, [0.0, 0.0])
            cell[0] += float(r["v"])
            cell[1] += float(r["q"])
        if other:
            cols.append("Others")
    rows = []
    cv = cq = 0.0
    tags = day_tags(pd.date_range(a, b, freq="D"))
    for day in pd.date_range(a, b, freq="D"):
        v, q = (float(tot.at[day, "v"]), float(tot.at[day, "q"])) if day in tot.index else (0.0, 0.0)
        lm = (day - pd.DateOffset(months=1)).normalize()
        ly = day - LY_DAYS * DAY
        lmv = tot.loc[lm] if lm in tot.index else None
        lyv = tot.loc[ly] if ly in tot.index else None
        cv += v
        cq += q
        rows.append({"day": day.strftime("%Y-%m-%d"), "label": f"{day.day} {day:%b}", "wd": f"{day:%a}",
                     "v": round(v), "q": round(q), "cv": round(cv), "cq": round(cq),
                     "lm": [round(float(lmv["v"])), round(float(lmv["q"]))] if lmv is not None else None,
                     "ly": [round(float(lyv["v"])), round(float(lyv["q"]))] if lyv is not None else None,
                     "cols": {k: [round(x[0]), round(x[1])] for k, x in split.get(day, {}).items()},
                     "tag": tags.get(day.strftime("%Y-%m-%d"))})
    sold = [r for r in rows if r["v"] or r["q"]]
    return {"scope": sel, "store_label": scope_label(sel), "start": a.strftime("%Y-%m-%d"), "end": b.strftime("%Y-%m-%d"),
            "range": fmt_range(a, b), "by": by if col else "none", "cols": cols, "rows": rows,
            "days_sold": len(sold), "total": {"v": round(cv), "q": round(cq)},
            "best": max(sold, key=lambda r: r["v"])["day"] if sold else None,
            "worst": min(sold, key=lambda r: r["v"])["day"] if len(sold) > 1 else None}


@app.get("/api/daywise")
def api_daywise():
    return api(lambda st: daywise_data(st, request.args))


# ════════════════════════════════════════════════════════════════════
#  ZERO SELL-OUT: models the store sells (or holds in stock) that sold nothing in the period, for the
#  store or for one SPC
# ════════════════════════════════════════════════════════════════════
def preset_window(p, dmax, args):
    p = p or "mtd"
    if p == "l7":
        return dmax - pd.Timedelta(days=6), dmax
    if p == "l15":
        return dmax - pd.Timedelta(days=14), dmax
    if p == "l30":
        return dmax - pd.Timedelta(days=29), dmax
    if p == "lm":
        e = dmax.replace(day=1) - DAY
        return e.replace(day=1), e
    if p == "custom":
        a, b = parse_date(args.get("start")), parse_date(args.get("end"))
        if a is not None and b is not None and a <= b:
            return a.normalize(), min(b.normalize(), dmax)
    return dmax.replace(day=1), dmax


def zero_core(daily, sel, a, b, ref_days=90, min_units=1, stock_models=None):
    """For the store scope: each model's units in a..b and in the reference window before it, and who sold it."""
    d = scope_rows(daily, sel)
    ref_a = a - pd.Timedelta(days=ref_days)
    ref = ov_slice(d, ref_a, a - DAY)
    cur = ov_slice(d, a, b)
    refm = ref.groupby("fam")["q"].sum()
    curm = cur.groupby("fam")["q"].sum()
    store_models = set(refm[refm >= min_units].index) | set(curm[curm > 0].index) | set(stock_models or [])
    store_models.discard("")
    store_models.discard("Unknown")
    return d, cur, ref, refm, curm, sorted(store_models)


def zero_data(st, args):
    daily = daily_frame(st)
    if daily is None or daily.empty:
        return {"error": "This sheet has no usable date column."}
    stores = sorted(s for s in daily["store"].unique() if s)
    sel = pick_scope(args, stores)
    dmax = daily["day"].max()
    a, b = preset_window(args.get("preset"), dmax, args)
    try:
        ref_days = max(14, min(365, int(args.get("ref", 90))))
    except ValueError:
        ref_days = 90
    stock_models = []
    stk = load_stock()
    for s in (sel or stores):
        if s in stk:
            stock_models += [it.get("model") for it in stk[s].get("items", []) if it.get("qty", 0) > 0 and it.get("model")]
    d, cur, ref, refm, curm, models = zero_core(daily, sel, a, b, ref_days, 1, stock_models if args.get("stock") == "1" else None)
    segmap = fam_segments(d)
    last = d.groupby("fam")["day"].max()
    in_stock = {}
    for s in (sel or stores):
        for it in (stk.get(s, {}).get("items") or []):
            if it.get("model"):
                in_stock[it["model"]] = in_stock.get(it["model"], 0) + int(it.get("qty") or 0)
    spcs_now = cur[cur["spc"] != ""].groupby("spc")["q"].sum().sort_values(ascending=False)
    spcs_ref = ref[ref["spc"] != ""].groupby("spc")["q"].sum()
    spc_list = list(spcs_now.index) + [s for s in spcs_ref.sort_values(ascending=False).index if s not in spcs_now.index]
    spc = (args.get("spc") or "").strip()
    seg = (args.get("seg") or "").strip()
    days = int((b - a).days) + 1

    def row(f):
        lr = last.get(f)
        return {"name": f, "seg": segmap.get(f, ""), "cur": round(float(curm.get(f, 0))), "ref": round(float(refm.get(f, 0))),
                "ref_rate": round(float(refm.get(f, 0)) / ref_days * days, 1),
                "last": lr.strftime("%Y-%m-%d") if lr is not None and not pd.isna(lr) else None,
                "since": int((b - lr).days) if lr is not None and not pd.isna(lr) else None,
                "stock": in_stock.get(f)}
    store_zero = [row(f) for f in models if curm.get(f, 0) <= 0]
    store_zero.sort(key=lambda r: (-(r["stock"] or 0), -r["ref"]))
    # every SPC against the models the store sold in the period
    sold_now = [f for f in models if curm.get(f, 0) > 0]
    by_spc_fam = cur[cur["spc"] != ""].groupby(["spc", "fam"])["q"].sum()
    # each SPC is measured against what their own store sold (several stores picked: each SPC's main store)
    both = pd.concat([ref, cur])
    home = both[both["spc"] != ""].groupby(["spc", "store"])["q"].sum().reset_index().sort_values("q", ascending=False).drop_duplicates("spc")
    home = dict(zip(home["spc"], home["store"]))
    store_cur = cur.groupby(["store", "fam"])["q"].sum()
    store_sold = {}
    for (stn, f), q in store_cur.items():
        if q > 0 and f in models:
            store_sold.setdefault(stn, {})[f] = float(q)
    matrix = []
    for s in spc_list:
        own = store_sold.get(home.get(s), {})
        own_list = sorted(own, key=lambda f: -own[f])
        sold = {f for (sp_, f), q in by_spc_fam.items() if sp_ == s and q > 0}
        zeros = [f for f in own_list if f not in sold]
        matrix.append({"spc": s, "store": home.get(s, ""), "units": round(float(spcs_now.get(s, 0))), "models_sold": len(sold & set(own_list)),
                       "store_models": len(own_list), "zero": len(zeros), "zero_top": zeros[:8],
                       "cover": round(len(sold & set(own_list)) / len(own_list) * 100, 1) if own_list else 0.0})
    matrix.sort(key=lambda r: (-r["zero"], r["units"]))
    spc_rows = []
    if spc:
        mine = d[d["spc"] == spc]
        if home.get(spc) and len(sel) != 1:   # the SPC's own store is the yardstick
            hc = ov_slice(d[d["store"] == home[spc]], a, b).groupby("fam")["q"].sum()
            curm, sold_now = hc, [f for f in models if hc.get(f, 0) > 0]
        mlast = mine.groupby("fam")["day"].max()
        mcur = ov_slice(mine, a, b).groupby("fam")["q"].sum()
        mref = ov_slice(mine, a - pd.Timedelta(days=ref_days), a - DAY).groupby("fam")["q"].sum()
        for f in sold_now + [f for f in models if f not in sold_now]:
            if mcur.get(f, 0) > 0:
                continue
            lr = mlast.get(f)
            spc_rows.append({"name": f, "seg": segmap.get(f, ""), "store_cur": round(float(curm.get(f, 0))),
                             "store_share": round(float(curm.get(f, 0)) / float(curm.sum()) * 100, 2) if curm.sum() else 0.0,
                             "mine_ref": round(float(mref.get(f, 0))), "stock": in_stock.get(f),
                             "last": lr.strftime("%Y-%m-%d") if lr is not None and not pd.isna(lr) else None,
                             "since": int((b - lr).days) if lr is not None and not pd.isna(lr) else None})
        spc_rows.sort(key=lambda r: (-r["store_cur"], -(r["stock"] or 0)))
    if seg:
        store_zero = [r for r in store_zero if r["seg"] == seg]
        spc_rows = [r for r in spc_rows if r["seg"] == seg]
    segs = sorted({segmap.get(f, "") for f in models} - {""})
    return {"stores": stores, "scope": sel, "store_label": scope_label(sel), "start": a.strftime("%Y-%m-%d"), "end": b.strftime("%Y-%m-%d"),
            "range": fmt_range(a, b), "days": days, "ref_days": ref_days, "preset": args.get("preset") or "mtd",
            "dmax": dmax.strftime("%Y-%m-%d"), "spcs": spc_list, "spc": spc, "seg": seg, "segs": segs,
            "models": len(models), "sold_now": len(sold_now), "store_zero": store_zero, "matrix": matrix, "spc_rows": spc_rows,
            "has_stock": bool(in_stock), "updated": updated_note()}


