# ════════════════════════════════════════════════════════════════════
#  STOCK & SELL-OUT: a stock statement (Excel or PDF, e.g. Tally's Stock Group Summary) against live sales
# ════════════════════════════════════════════════════════════════════
STOCK_PATH = os.path.join(UPLOAD_DIR, "stock.json")
_AMT = re.compile(r"-?\d{1,3}(?:,\d{2,3})*(?:\.\d+)?|-?\d+(?:\.\d+)?")
_QTY = re.compile(r"(-?[\d,]+(?:\.\d+)?)\s*(?:Nos|Pcs|No|Units?|Qty)\b\.?", re.I)
_SKU = re.compile(r"\s*-\s*([A-Z]{2,3}-[A-Z0-9]{4,}(?:/[A-Z0-9]+)?)_?\s*$")
_SKIP = ("carriedover", "broughtforward", "grandtotal", "continued", "particulars", "closingbalance", "valueratequantity",
         "quantityratevalue", "stockgroupsummary", "page")


def load_stock():
    try:
        with open(STOCK_PATH, encoding="utf-8") as fh:
            d = json.load(fh)
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def save_stock(d):
    tmp = STOCK_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(d, fh)
    os.replace(tmp, STOCK_PATH)


def _num(s):
    try:
        return float(str(s).replace(",", "").strip())
    except ValueError:
        return None


def stock_line(line):
    """'Samsung Galaxy A17 5G 6/128GB Gray - SM-A176BZALINS 7 Nos 19,759.81 1,38,318.70' (any order of the numbers)
    -> {name, sku, qty, rate, value}; None for headers, totals and lines without a quantity."""
    t = re.sub(r"\s+", " ", line).strip()
    if not t:
        return None
    flat = re.sub(r"[^a-z]", "", t.lower())
    if any(flat.startswith(k) for k in _SKIP) or "grandtotal" in flat or "carriedover" in flat or "broughtforward" in flat:
        return None
    mq = _QTY.search(t)
    if not mq:
        return None
    qty = _num(mq.group(1))
    rest = (t[:mq.start()] + " " + t[mq.end():]).strip()
    # the numbers at the end are the rate and value; the name is what comes before them
    tail = re.search(r"((?:\s+-?[\d,]+\.\d{2})+)\s*$", " " + rest)
    nums = [_num(x) for x in re.findall(r"-?[\d,]+\.\d{2}", tail.group(1))] if tail else []
    name = rest[:len(rest) - len(tail.group(1)) + 1].strip() if tail else rest
    name = re.sub(r"\s+", " ", name).strip(" -")
    if not name or qty is None:
        return None
    sku = ""
    m = _SKU.search(name)
    if m:
        sku, name = m.group(1), name[:m.start()].strip(" -")
    nums = [x for x in nums if x is not None]
    rate = value = None
    if len(nums) >= 2:
        value, rate = max(nums[-2:], key=abs), min(nums[-2:], key=abs)
    elif len(nums) == 1:
        value = nums[0]
        rate = value / qty if qty else None
    return {"name": name, "sku": sku, "qty": int(round(qty)), "rate": round(rate, 2) if rate else 0.0,
            "value": round(value, 2) if value else round((rate or 0) * qty, 2)}


def stock_lines(lines):
    items, buf = [], ""
    for ln in lines:
        ln = ln.rstrip()
        if not ln.strip():
            continue
        cand = (buf + " " + ln).strip() if buf else ln
        it = stock_line(cand)
        if it:
            items.append(it)
            buf = ""
            continue
        flat = re.sub(r"[^a-z]", "", cand.lower())
        # a name broken over two lines ('… Violet - SM-' then 'S948BZVBINS 3 Nos …') is joined; headers are dropped
        buf = cand if re.search(r"(?:-\s*[A-Z]{0,3}-?|\b(?:Samsung|Galaxy)\b.*)$", ln) and len(cand) < 200 and not any(k in flat for k in _SKIP[:3]) else ""
    return items


def stock_header(text):
    info = {}
    m = re.search(r"\bto\s+(\d{1,2}\s*-\s*[A-Za-z]{3}\s*-?\s*\d{2,4})", text)
    if m:
        t = pd.to_datetime(re.sub(r"\s+", "", m.group(1)), format="mixed", dayfirst=True, errors="coerce")
        if not pd.isna(t):
            info["as_of"] = t.strftime("%Y-%m-%d")
    m = re.search(r"Grand\s*Total\s+([\d,]+\.\d{2})\s+([\d,]+)\s*Nos|G\s*r\s*a\s*n\s*d\s+T\s*o\s*t\s*a\s*l\s+([\d,]+\.\d{2})\s+([\d,]+)\s*Nos", text)
    if not m:
        m2 = re.search(r"Grand\s*Total\s+([\d,]+)\s*Nos\s+([\d,]+\.\d{2})", text)
        if m2:
            info["grand"] = {"qty": int(_num(m2.group(1))), "value": _num(m2.group(2))}
    else:
        g = [x for x in m.groups() if x]
        info["grand"] = {"value": _num(g[0]), "qty": int(_num(g[1]))}
    info["head"] = re.sub(r"\s+", " ", text[:600])
    return info


def read_stock_file(raw, name):
    ext = name.rsplit(".", 1)[-1].lower() if "." in name else ""
    if ext == "pdf" or raw[:5] == b"%PDF-":
        if raw[:5] != b"%PDF-":
            raise ValueError("this .pdf file is not a real PDF")
        text = ""
        try:
            import pdfplumber
            with pdfplumber.open(io.BytesIO(raw)) as pdf:
                text = "\n".join((p.extract_text() or "") for p in pdf.pages)
        except ImportError:
            try:
                import pypdf
            except ImportError:
                raise ValueError("reading PDFs needs the pdfplumber or pypdf package on the server (add it to requirements.txt)")
            text = "\n".join((p.extract_text() or "") for p in pypdf.PdfReader(io.BytesIO(raw)).pages)
        if not text.strip():
            raise ValueError("this PDF has no text in it (a scanned image); export it from Tally as PDF or Excel instead")
        return stock_lines(text.splitlines()), stock_header(text)
    if ext not in ("xlsx", "xls", "csv"):
        raise ValueError("only .xlsx, .xls, .csv or .pdf files are accepted")
    if ext == "xlsx" and not raw.startswith(b"PK\x03\x04"):
        raise ValueError("this .xlsx file is not a real Excel workbook")
    buf = io.BytesIO(raw)
    try:
        sheet = pd.read_csv(buf, header=None, dtype=str) if ext == "csv" else pd.read_excel(buf, header=None, dtype=str)
    except ImportError:
        raise ValueError("reading old .xls files needs the xlrd package on the server; save it as .xlsx instead")
    sheet = sheet.fillna("")
    text = "\n".join(" ".join(str(x) for x in r if str(x).strip()) for r in sheet.head(15).values)
    head = stock_header(text)
    # a sheet with a header row: name / SKU / quantity / rate / value columns
    hdr_row, cols = None, {}
    for i, r in enumerate(sheet.head(30).values):
        low = [str(x).strip().lower() for x in r]
        q = next((j for j, x in enumerate(low) if re.search(r"\b(?:qty|quantity|closing|stock|balance|nos)\b", x)), None)
        n = next((j for j, x in enumerate(low) if re.search(r"particular|item|description|product|model|name|material", x)), None)
        if q is not None and n is not None and q != n:
            hdr_row = i
            cols = {"name": n, "qty": q,
                    "sku": next((j for j, x in enumerate(low) if re.search(r"\bsku\b|item code|product code|model code|material code|part", x)), None),
                    "rate": next((j for j, x in enumerate(low) if re.search(r"\brate\b|\bprice\b|\bdp\b|\bcost\b", x)), None),
                    "value": next((j for j, x in enumerate(low) if re.search(r"\bvalue\b|\bamount\b", x)), None)}
            break
    items = []
    if hdr_row is not None:
        for r in sheet.values[hdr_row + 1:]:
            name = str(r[cols["name"]]).strip()
            flat = re.sub(r"[^a-z]", "", name.lower())
            q = _num(re.sub(r"[^\d.,-]", "", str(r[cols["qty"]])) or "x")
            if not name or q is None or any(flat.startswith(k) for k in _SKIP[:3]) or flat in ("total", "grandtotal"):
                continue
            sku = str(r[cols["sku"]]).strip() if cols["sku"] is not None else ""
            if not sku:
                m = _SKU.search(name)
                if m:
                    sku, name = m.group(1), name[:m.start()].strip(" -")
            rate = _num(str(r[cols["rate"]]).replace(",", "")) if cols["rate"] is not None else None
            value = _num(str(r[cols["value"]]).replace(",", "")) if cols["value"] is not None else None
            items.append({"name": re.sub(r"\s+", " ", name), "sku": sku.strip("_ "), "qty": int(round(q)),
                          "rate": round(rate or ((value or 0) / q if q else 0), 2), "value": round(value if value is not None else (rate or 0) * q, 2)})
    if not items:   # a Tally layout pasted into Excel: read each row as a line of text
        items = stock_lines([" ".join(str(x) for x in r if str(x).strip()) for r in sheet.values])
    return items, head


_NAME_DROP = re.compile(r"\b(?:samsung|galaxy)\b", re.I)


def _norm_model(s):
    s = _NAME_DROP.sub(" ", str(s).lower())
    s = re.sub(r"\bplus\b", "+", s)
    return re.sub(r"[^a-z0-9+]", "", s)


def sku_key(s):
    s = re.sub(r"[\s_]+", "", str(s or "").upper())
    return re.sub(r"(?:INS|INU)$", "", s)


def stock_model(name, fam_norms):
    """The sales model a stock line belongs to: the longest model name found in it ('Galaxy S26 Ultra 12/256GB' -> 'S26 Ultra')."""
    n = _norm_model(name)
    best = ""
    for fam, fn in fam_norms:
        if fn and fn in n and len(fn) > len(_norm_model(best)):
            best = fam
    if best:
        return best, True
    # not sold yet: the name up to the memory / size, without the colour ('Galaxy Tab S10 Lite Wifi 6/128GB Gray' -> 'Tab S10 Lite Wifi',
    # 'Watch Ultra2 Titanium Black 47MM' -> 'Watch Ultra2')
    t = _NAME_DROP.sub(" ", str(name))
    t = re.split(r"\(|\b\d+\s*/\s*\d+\s*(?:GB|TB)?\b|\b\d+\s*(?:GB|TB)\b|\b\d{2}\s*mm\b", t, maxsplit=1, flags=re.I)[0]
    t = strip_colors(re.sub(r"\s+", " ", t).strip(" -"))
    return t or str(name), False


def match_stock_store(head, stores, wanted=""):
    """The store named in the statement's heading (e.g. '… Anna Nagar, Chennai'); else the store picked on the page."""
    low = (head or "").lower()
    best, score = "", 0
    for s in stores:
        part = re.findall(r"\(([^)]+)\)", s)
        keys = [p.strip().lower() for p in part] or [s.lower()]
        for k in keys:
            if k and re.search(r"(?<![a-z0-9])" + re.escape(k) + r"(?![a-z0-9])", low) and len(k) > score:
                best, score = s, len(k)
    return best or (wanted if wanted in stores else "")


def sku_col(df):
    cols = list(df.columns)
    return find_col(cols, ("sku",), ("product", "code"), ("material", "code"), ("item", "code"), ("model", "code"))


def stock_mapper(st, store, since):
    """(SKU key -> model, SKU key -> units since `since`) from the sales rows of one store, when the sheet has a SKU column."""
    df, ctx = st["df"], st["ctx"]
    sk = sku_col(df)
    ch = find_col(list(df.columns), ("channel", "name"), ("channel",))
    if not (sk and ch and ctx["date"]):
        return {}, {}
    part = df[df[ch].fillna("").astype(str).str.strip() == store]
    keys = part[sk].map(sku_key)
    sku_fam = {}
    if ctx["fam"] and len(part):
        sku_fam = part.assign(_k=keys).groupby("_k")[ctx["fam"]].agg(lambda s: s.mode().iat[0] if len(s.mode()) else "").to_dict()
    recent = part[part[ctx["date"]].dt.normalize() >= since]
    qc = ctx["qty"] if ctx["qty"] and pd.api.types.is_numeric_dtype(part[ctx["qty"]]) else ""
    w = pd.to_numeric(recent[qc], errors="coerce").fillna(0) if qc else pd.Series(1.0, index=recent.index)
    return sku_fam, w.groupby(recent[sk].map(sku_key)).sum().to_dict()


def map_stock_item(it, sku_fam, fam_norms):
    k = sku_key(it.get("sku"))
    if k and sku_fam.get(k):
        return sku_fam[k], True
    return stock_model(it["name"], fam_norms)


FEST_PRE, FEST_POST = 10, 2   # a festival's selling window: 10 days before it to 2 days after
STOCK_BASIS = {"blend": "Recent pace (60% last 7 days + 40% last 30)", "mtd": "MTD pace", "lmtd": "LMTD pace (same days last month)",
               "lm": "Last month (full)", "l30": "Last 30 days", "l90": "Last 90 days", "fest": "Festival: last year's sell-out"}


def stock_analysis(st, store, cover=15, lead=3, basis="blend", fest="", norms=None):
    daily = daily_frame(st)
    stores = sorted(s for s in daily["store"].unique() if s) if daily is not None else []
    stk = load_stock()
    rec = stk.get(store)
    basis = basis if basis in STOCK_BASIS else "blend"
    out = {"stores": stores, "store": store, "loaded": sorted(k for k in stk if not k.startswith("_")), "cover": cover, "lead": lead,
           "basis": basis, "bases": [{"key": k, "label": v} for k, v in STOCK_BASIS.items()]}
    if not rec:
        return {**out, "empty": True}
    fams = json.loads(st["ctx"]["boot_json"]).get("family_names", [])
    fam_norms = [(f, _norm_model(f)) for f in fams]
    d = daily[daily["store"] == store] if daily is not None else None
    dmax = d["day"].max() if d is not None and len(d) else (daily["day"].max() if daily is not None else eod_today())
    a7, a30 = dmax - pd.Timedelta(days=6), dmax - pd.Timedelta(days=29)
    mtd_a = dmax.replace(day=1)
    lm_a, lm_b = month_back(mtd_a, 1, (dmax - mtd_a).days)
    segmap = fam_segments(d) if d is not None else {}
    by = lambda a, b: ov_slice(d, a, b).groupby("fam")[["q", "v"]].sum() if d is not None else pd.DataFrame(columns=["q", "v"])
    s7, s30, smtd, slm = by(a7, dmax), by(a30, dmax), by(mtd_a, dmax), by(lm_a, lm_b)
    s90 = by(dmax - pd.Timedelta(days=89), dmax)
    lmf_b = mtd_a - DAY
    lmf_a = lmf_b.replace(day=1)
    slmf = by(lmf_a, lmf_b)
    mtd_days, lm_days, lmf_days = (dmax - mtd_a).days + 1, (lm_b - lm_a).days + 1, (lmf_b - lmf_a).days + 1
    last_sale = d.groupby("fam")["day"].max() if d is not None else {}
    sku_fam, sku30 = stock_mapper(st, store, a30)
    asof = parse_date(rec.get("as_of")) or dmax
    norms = {k: int(v) for k, v in (norms if norms is not None else (rec.get("norms") or {})).items() if str(v).isdigit() and 1 <= int(v) <= 120}
    # festival plan: last year's sales around the same festival (whatever its date was), grown by the store's trend
    fest_opts = festival_options(max(asof, dmax))
    fest_info, sfest, growth, win_days = None, None, 1.0, FEST_PRE + FEST_POST + 1
    if basis == "fest":
        fsel = next((x for x in fest_opts if x["key"] == fest), fest_opts[0] if fest_opts else None)
        if fsel and d is not None:
            ly = pd.Timestamp(fsel["ly"])
            fa, fb = ly - pd.Timedelta(days=FEST_PRE), ly + pd.Timedelta(days=FEST_POST)
            sfest = by(fa, fb)
            cur30 = float(ov_slice(d, a30, dmax)["q"].sum())
            ly30 = float(ov_slice(d, a30 - pd.DateOffset(years=1), dmax - pd.DateOffset(years=1))["q"].sum())
            growth = min(2.0, max(0.5, cur30 / ly30)) if ly30 else 1.0
            fest_info = {**fsel, "window": fmt_range(fa, fb), "ly_units": round(float(sfest["q"].sum())) if len(sfest) else 0,
                         "growth": round(growth, 2), "has_ly": bool(len(sfest)), "days": win_days}
        if not fest_info or not fest_info["has_ly"]:
            out["fest_note"] = ("No festival in the calendar for the next 150 days." if not fest_opts else
                                f"The sheet has no sales around {fest_opts[0]['name']} last year ({fest_opts[0]['ly']}), so the recent pace is used.")
            basis, sfest = "blend", None
    out.update(basis=basis, fest=fest_info, fests=fest_opts, norms=norms)
    models = {}
    for it in rec.get("items", []):
        k = sku_key(it.get("sku"))
        fam, known = map_stock_item(it, sku_fam, fam_norms)
        m = models.setdefault(fam, {"name": fam, "known": known, "stock": 0, "value": 0.0, "skus": []})
        m["stock"] += int(it.get("qty") or 0)
        m["value"] += float(it.get("value") or 0)
        var, col = stock_variant(it["name"], fam)
        m["skus"].append({"name": it["name"], "short": stock_short(it["name"], fam), "variant": var, "color": col, "sku": it.get("sku", ""),
                          "qty": int(it.get("qty") or 0), "rate": it.get("rate", 0),
                          "value": it.get("value", 0), "s30": round(float(sku30.get(k, 0))) if sku30 else None})
    # models selling in the last 30 days with no stock at all
    for fam in s30.index:
        if fam and fam not in models and fam != "Unknown" and float(s30.at[fam, "q"]) > 0:
            models[fam] = {"name": fam, "known": True, "stock": 0, "value": 0.0, "skus": []}
    rows = []
    for fam, m in models.items():
        q7 = float(s7.at[fam, "q"]) if fam in s7.index else 0.0
        q30 = float(s30.at[fam, "q"]) if fam in s30.index else 0.0
        v30 = float(s30.at[fam, "v"]) if fam in s30.index else 0.0
        qv = lambda fr: float(fr.at[fam, "q"]) if fam in fr.index else 0.0
        if basis == "mtd":
            rate = qv(smtd) / mtd_days
        elif basis == "lmtd":
            rate = qv(slm) / lm_days
        elif basis == "lm":
            rate = qv(slmf) / lmf_days
        elif basis == "l30":
            rate = q30 / 30
        elif basis == "l90":
            rate = qv(s90) / 90
        elif basis == "fest":
            rate = qv(sfest) * growth / win_days
        else:
            rate = 0.6 * q7 / 7 + 0.4 * q30 / 30   # recent days count more, so a model picking up is caught early
            if q7 == 0 and q30 > 0:
                rate = q30 / 30 * 0.5
        seg_m = segmap.get(fam) or guess_seg(fam, segmap)
        nd = win_days if basis == "fest" else norms.get(seg_m, cover)   # stock norm: days of cover to hold
        price = v30 / q30 if q30 else (m["value"] / m["stock"] if m["stock"] else 0)
        cov = m["stock"] / rate if rate > 0 else None
        need = max(0, int(-(-(rate * (nd + lead) - m["stock"]) // 1))) if rate > 0 else 0
        norm_qty = int(-(-(rate * nd) // 1)) if rate > 0 else 0
        sold_any = q30 > 0 or rate > 0
        if m["stock"] <= 0:
            status = "out"
        elif not sold_any:
            status = "dead"
        elif cov is not None and cov <= lead + 2:
            status = "critical"
        elif cov is not None and cov < nd:
            status = "low"
        elif cov is not None and cov > max(60, nd * 4):
            status = "excess"
        else:
            status = "ok"
        trend = "up" if q30 and q7 / 7 > q30 / 30 * 1.25 else "down" if q30 and q7 / 7 < q30 / 30 * 0.75 else "flat"
        lr = last_sale.get(fam) if hasattr(last_sale, "get") else None
        rows.append({"name": fam, "seg": seg_m, "known": m["known"], "stock": m["stock"], "value": round(m["value"]),
                     "norm": nd, "norm_qty": norm_qty, "gap": norm_qty - m["stock"], "s90": round(qv(s90)), "lm": round(qv(slmf)),
                     "fest_q": round(qv(sfest) * growth) if sfest is not None else None,
                     "s7": round(q7), "s30": round(q30), "mtd": round(float(smtd.at[fam, "q"])) if fam in smtd.index else 0,
                     "lmtd": round(float(slm.at[fam, "q"])) if fam in slm.index else 0, "v30": round(v30),
                     "rate": round(rate, 2), "cover": round(cov, 1) if cov is not None else None,
                     "runout": (asof + pd.Timedelta(days=int(cov))).strftime("%Y-%m-%d") if cov is not None else None,
                     "need": need, "need_v": round(need * price), "status": status, "trend": trend, "price": round(price),
                     "last": lr.strftime("%Y-%m-%d") if lr is not None and not pd.isna(lr) else None,
                     "skus": sorted(m["skus"], key=lambda x: -x["qty"])})
    order = {"out": 0, "critical": 1, "low": 2, "ok": 3, "excess": 4, "dead": 5}
    rows.sort(key=lambda r: (order[r["status"]], -(r["s30"]), -r["value"]))
    tot_q = sum(r["stock"] for r in rows)
    tot_v = sum(r["value"] for r in rows)
    tot_rate = sum(r["rate"] for r in rows if r["stock"] > 0)
    cnt = lambda s: sum(1 for r in rows if r["status"] == s)
    # segment mix: share of stock against share of the last 30 days' sales
    seg_rows = {}
    for r in rows:
        g = seg_rows.setdefault(r["seg"] or "Other", {"name": r["seg"] or "Other", "stock": 0, "value": 0, "s30": 0, "v30": 0, "rate": 0.0})
        g["stock"] += r["stock"]
        g["value"] += r["value"]
        g["s30"] += r["s30"]
        g["v30"] += r["v30"]
        g["rate"] += r["rate"] if r["stock"] > 0 else 0
    s30_tot = sum(g["s30"] for g in seg_rows.values()) or 1
    segs = []
    for g in sorted(seg_rows.values(), key=lambda g: -g["value"]):
        g["stock_share"] = round(g["stock"] / (tot_q or 1) * 100, 1)
        g["sales_share"] = round(g["s30"] / s30_tot * 100, 1)
        g["cover"] = round(g["stock"] / g["rate"], 1) if g["rate"] else None
        g["rate"] = round(g["rate"], 2)
        segs.append(g)
    colors = {}
    for r in rows:
        for x in r["skus"]:
            c = colors.setdefault(x["color"], {"color": x["color"], "stock": 0, "value": 0.0, "s30": 0, "known": False, "models": set()})
            c["stock"] += x["qty"]
            c["value"] += float(x["value"] or 0)
            if x["s30"] is not None:
                c["s30"] += x["s30"]
                c["known"] = True
            c["models"].add(r["name"])
    color_rows = sorted(({**c, "value": round(c["value"]), "models": len(c["models"]), "share": round(c["stock"] / (tot_q or 1) * 100, 1)}
                         for c in colors.values()), key=lambda c: -c["stock"])
    need_rows = [r for r in rows if r["need"] > 0]
    dead_v = sum(r["value"] for r in rows if r["status"] == "dead")
    excess_v = sum(r["value"] for r in rows if r["status"] == "excess")
    actions = []
    outs = [r for r in rows if r["status"] == "out"]
    if outs:
        lost = sum(r["rate"] * r["price"] for r in outs)
        actions.append({"tone": "bad", "text": f"<b>{len(outs)} selling model{'s' if len(outs) != 1 else ''} out of stock</b>: "
                        + ", ".join(f"{esc_html(r['name'])} ({r['s30']} sold in 30 days)" for r in outs[:4])
                        + f". About <b>{inr_short(lost)}</b> of sales a day is at risk; order these first."})
    crit = [r for r in rows if r["status"] == "critical"]
    if crit:
        actions.append({"tone": "bad", "text": f"<b>{len(crit)} model{'s' if len(crit) != 1 else ''} run out within {lead + 2} days</b>: "
                        + ", ".join(f"{esc_html(r['name'])} ({r['stock']} left, ~{r['cover']:g} days)" for r in crit[:4]) + "."})
    low = [r for r in rows if r["status"] == "low"]
    if low:
        actions.append({"tone": "warn", "text": f"<b>{len(low)} model{'s' if len(low) != 1 else ''} below {cover} days of cover</b>; "
                        f"top up {', '.join(esc_html(r['name']) for r in low[:4])}."})
    if need_rows:
        actions.append({"tone": "info", "text": f"Suggested order for {cover} days of cover plus {lead} days' lead time: "
                        f"<b>{sum(r['need'] for r in need_rows)} units</b> across {len(need_rows)} models, about <b>{inr_short(sum(r['need_v'] for r in need_rows))}</b>."})
    if dead_v:
        dead = sorted([r for r in rows if r["status"] == "dead"], key=lambda r: -r["value"])
        actions.append({"tone": "warn", "text": f"<b>{inr_short(dead_v)}</b> is held in {len(dead)} model{'s' if len(dead) != 1 else ''} with no sale in 30 days "
                        f"({', '.join(esc_html(r['name']) for r in dead[:4])}): push with SPC incentives or move them to a busier store."})
    if excess_v:
        exc = sorted([r for r in rows if r["status"] == "excess"], key=lambda r: -r["value"])
        actions.append({"tone": "info", "text": f"<b>{inr_short(excess_v)}</b> is over-stocked (more than {max(60, cover * 4)} days of cover) in "
                        f"{', '.join(esc_html(r['name']) for r in exc[:4])}: hold re-orders for these."})
    up = [r for r in rows if r["trend"] == "up" and r["stock"] > 0 and r["status"] in ("low", "critical", "ok")]
    if up:
        actions.append({"tone": "good", "text": "Picking up this week (last 7 days well above the 30-day pace): "
                        + ", ".join(f"{esc_html(r['name'])}" for r in up[:5]) + ". Keep them filled."})
    mism = [g for g in segs if g["stock_share"] - g["sales_share"] >= 10]
    if mism:
        g = mism[0]
        actions.append({"tone": "warn", "text": f"{esc_html(g['name'])} holds {g['stock_share']:g}% of the stock but brings {g['sales_share']:g}% of 30-day unit sales: rebalance the next order."})
    grand = (rec.get("head_info") or {}).get("grand")
    return {**out, "empty": False, "file": rec.get("file"), "uploaded": rec.get("uploaded"), "as_of": rec.get("as_of"), "colors": color_rows,
            "seg_list": sorted({r["seg"] for r in rows if r["seg"]}), "basis_label": STOCK_BASIS[basis],
            "sales_to": dmax.strftime("%Y-%m-%d"), "check": rec.get("check", ""),
            "kpis": {"stock": tot_q, "value": round(tot_v), "models": sum(1 for r in rows if r["stock"] > 0),
                     "cover": round(tot_q / tot_rate, 1) if tot_rate else None, "rate": round(tot_rate, 2),
                     "out": cnt("out"), "critical": cnt("critical"), "low": cnt("low"), "ok": cnt("ok"), "excess": cnt("excess"), "dead": cnt("dead"),
                     "dead_v": round(dead_v), "excess_v": round(excess_v), "need": sum(r["need"] for r in need_rows),
                     "need_v": round(sum(r["need_v"] for r in need_rows)), "grand": grand},
            "models": rows, "segments": segs, "actions": actions, "updated": updated_note()}


_SEG_KIND = [(r"^\s*tab", "tab"), (r"\b(?:watch|buds|ring|fit)", "wear"), (r"\bbook", "pc"),
             (r"\b(?:z\s*)?(?:fold|flip)", "fold"), (r"^\s*s\d{2}", "s"), (r"^\s*[amf]\d{2}", "a")]


def guess_seg(name, segmap):
    """The segment of a model the sheet has not sold yet, from a sold model of the same kind (A27 -> like A17)."""
    def kind(n):
        low = _NAME_DROP.sub(" ", str(n).lower()).strip()
        return next((k for pat, k in _SEG_KIND if re.search(pat, low)), "")
    k = kind(name)
    if not k:
        return ""
    votes = {}
    for f, sg in segmap.items():
        if sg and kind(f) == k:
            votes[sg] = votes.get(sg, 0) + 1
    return max(votes, key=votes.get) if votes else ""


def stock_short(name, model):
    """'Samsung Galaxy A17 5G 6/128GB Gray' under the model 'A17 5G' -> '6/128GB Gray'."""
    t = re.sub(r"\s+", " ", _NAME_DROP.sub(" ", str(name))).strip()
    m = re.match(re.escape(str(model)).replace(r"\ ", r"\s*") + r"\b\s*", t, re.I)
    rest = t[m.end():].strip(" -") if m else ""
    return rest or t


def esc_html(s):
    return str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


@app.get("/stock")
def stock_page():
    return page(STOCK_HTML)


@app.get("/api/stock")
def api_stock():
    def run(st):
        daily = daily_frame(st)
        stores = sorted(s for s in daily["store"].unique() if s) if daily is not None else []
        stk = load_stock()
        want = request.args.get("store", "")
        store = want if want in stores else next((s for s in stores if s in stk), stores[0] if stores else "")
        try:
            cover = max(3, min(90, int(request.args.get("cover", 15))))
            lead = max(0, min(30, int(request.args.get("lead", 3))))
        except ValueError:
            cover, lead = 15, 3
        try:
            return stock_analysis(st, store, cover, lead, request.args.get("basis", "blend"), request.args.get("fest", ""))
        except Exception as exc:  # noqa: BLE001 - one bad stock line never takes the page down
            return {"stores": stores, "store": store, "error": f"Could not analyse this store's stock: {exc}. Upload the file again."}
    return api(run)


@app.post("/api/stock")
@admin_api
def api_stock_post():
    st = get_state()
    if st is None:
        return jsonify({"error": "Upload the sales sheet first."}), 400
    f = request.files.get("file")
    if not f or not f.filename:
        return jsonify({"error": "Choose a stock file first."}), 400
    name = os.path.basename(f.filename)[:120]
    raw = f.read()
    if len(raw) > 20 * 1024 * 1024:
        return jsonify({"error": "That stock file is over 20 MB."}), 400
    try:
        items, head = read_stock_file(raw, name)
    except Exception as exc:  # noqa: BLE001 - shown to the user
        return jsonify({"error": f"Couldn't read that stock file: {exc}"}), 400
    items = [it for it in items if it["qty"] != 0 or it["value"]]
    if not items:
        return jsonify({"error": "No stock lines were found in that file (each line needs a model name and a quantity, e.g. '7 Nos')."}), 400
    daily = daily_frame(st)
    stores = sorted(s for s in daily["store"].unique() if s) if daily is not None else []
    page_store = request.form.get("store", "") if request.form.get("store", "") in stores else ""
    file_store = match_stock_store(head.get("head", ""), stores)
    choice = request.form.get("use", "")
    if choice == "file" and file_store:
        store = file_store
    elif choice == "page" and page_store:
        store = page_store
    elif file_store and page_store and file_store != page_store:
        # never switch stores silently: the page asks which store this file is for
        return jsonify({"mismatch": True, "file_store": file_store, "page_store": page_store,
                        "error": f"This file is for {file_store}, but {page_store} is picked."}), 409
    else:
        store = page_store or file_store
    if not store:
        return jsonify({"error": "Pick the store this stock belongs to at the top, then upload again.", "need_store": True}), 400
    tq, tv = sum(it["qty"] for it in items), round(sum(it["value"] for it in items), 2)
    g = head.get("grand")
    check = ""
    if g:
        ok = g.get("qty") == tq and abs((g.get("value") or 0) - tv) < 1
        check = (f"Matches the Grand Total ({g['qty']} Nos, {inr_full(g['value'])})" if ok
                 else f"Grand Total says {g.get('qty')} Nos / {inr_full(g.get('value') or 0)}; {tq} Nos / {inr_full(tv)} were read")
    fam_norms = [(x, _norm_model(x)) for x in json.loads(st["ctx"]["boot_json"]).get("family_names", [])]
    sku_fam, _s = stock_mapper(st, store, daily["day"].max() - pd.Timedelta(days=29))
    for it in items:
        it["model"] = map_stock_item(it, sku_fam, fam_norms)[0]
    stk = load_stock()
    old_norms = (stk.get(store) or {}).get("norms") or {}
    stk[store] = {"norms": old_norms, "items": items, "file": name, "uploaded": datetime.now().strftime("%d %b %Y, %I:%M %p"),
                  "as_of": head.get("as_of") or eod_today().strftime("%Y-%m-%d"), "check": check,
                  "head_info": {"grand": g} if g else {}}
    save_stock(stk)
    audit("stock uploaded", f"{store} · {name} · {tq} units")
    res = stock_analysis(st, store)
    res["saved"] = f"{len(items)} lines, {tq} units read for {store}."
    return jsonify(res)


