# ════════════════════════════════════════════════════════════════════
#  WEEKLY DUTY ROSTER: shifts and week-offs for each store's SPCs, Monday to Sunday
# ════════════════════════════════════════════════════════════════════
ROSTER_PATH = os.path.join(UPLOAD_DIR, "roster.json")
DEFAULT_SHIFTS = [
    {"code": "M", "name": "Morning", "start": "09:30", "end": "18:30", "color": "#0a84ff"},
    {"code": "E", "name": "Evening", "start": "12:30", "end": "21:30", "color": "#af52de"},
    {"code": "G", "name": "General", "start": "10:30", "end": "19:30", "color": "#34c759"},
    {"code": "WO", "name": "Week off", "start": "", "end": "", "color": "#8e8e93"},
    {"code": "L", "name": "Leave", "start": "", "end": "", "color": "#ff9500"},
]
WORK_CODES = {"M", "E", "G"}


def load_roster():
    try:
        with open(ROSTER_PATH, encoding="utf-8") as fh:
            d = json.load(fh)
        if isinstance(d, dict):
            d.setdefault("weeks", {})
            d.setdefault("shifts", {})
            return d
    except (OSError, ValueError):
        pass
    return {"weeks": {}, "shifts": {}}


def save_roster(d):
    tmp = ROSTER_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(d, fh)
    os.replace(tmp, ROSTER_PATH)


def monday(d):
    return (d - pd.Timedelta(days=d.weekday())).normalize()


def roster_suggest(spcs, load, prev, week_no):
    """Week-offs on the store's quietest weekdays (never its two busiest), each SPC's day moving on one from last week
    so nobody keeps the same day; Morning / Evening alternating per SPC and per week, balanced each day."""
    n = len(spcs)
    if not n:
        return {}
    order = sorted(range(7), key=lambda i: (load[i], i))
    busy = set(sorted(range(7), key=lambda i: -load[i])[:2])
    allowed = [i for i in order if i not in busy] or order
    cap = max(1, -(-n // len(allowed)))
    count = [0] * 7
    off = {}
    for k, s in enumerate(spcs):
        want = None
        if prev and s in prev and "WO" in prev[s]:
            last = prev[s].index("WO")
            if last in allowed:   # next quiet day after last week's
                want = allowed[(allowed.index(last) + 1) % len(allowed)]
        cands = ([want] if want is not None else []) + [allowed[(k + j) % len(allowed)] for j in range(len(allowed))]
        day = next((c for c in cands if count[c] < cap), allowed[k % len(allowed)])
        off[s] = day
        count[day] += 1
    grid = {}
    for k, s in enumerate(spcs):
        shift = "M" if (k + week_no) % 2 == 0 else "E"
        grid[s] = ["WO" if i == off[s] else shift for i in range(7)]
    for i in range(7):   # balance each day: no more than one more on a shift than the other; the extra works General
        m = [s for s in spcs if grid[s][i] == "M"]
        e = [s for s in spcs if grid[s][i] == "E"]
        while abs(len(m) - len(e)) > 1:
            big = m if len(m) > len(e) else e
            mv = big.pop()
            grid[mv][i] = "G"
    return grid


def roster_data(st, args):
    daily = daily_frame(st)
    if daily is None or daily.empty:
        return {"error": "This sheet has no usable date column."}
    stores = sorted(s for s in daily["store"].unique() if s)
    sel = pick_scope(args, stores)
    store = sel[0] if sel else stores[0]
    dmax = daily["day"].max()
    wk = parse_date(args.get("week"))
    wk = monday(wk if wk is not None else eod_today().normalize())
    days = [wk + pd.Timedelta(days=i) for i in range(7)]
    d = daily[daily["store"] == store]
    # the store's usual sales on each weekday, from the last 8 weeks of data
    hist = ov_slice(d, dmax - pd.Timedelta(days=55), dmax)
    by_day = hist.groupby("day")[["v", "q"]].sum()
    wd = by_day.groupby(by_day.index.weekday).mean()
    load = [float(wd.at[i, "v"]) if i in wd.index else 0.0 for i in range(7)]
    loadq = [float(wd.at[i, "q"]) if i in wd.index else 0.0 for i in range(7)]
    act = ov_slice(d, dmax - pd.Timedelta(days=44), dmax)
    act = act[act["spc"] != ""].groupby("spc")[["v", "q"]].sum().sort_values("v", ascending=False)
    R = load_roster()
    key = f"{store}|{wk:%Y-%m-%d}"
    saved = R["weeks"].get(key)
    prev = R["weeks"].get(f"{store}|{(wk - pd.Timedelta(days=7)):%Y-%m-%d}")
    spcs = list(act.index)
    for s in ((saved or {}).get("spcs") or []) + ((prev or {}).get("spcs") or []):
        if s not in spcs:
            spcs.append(s)
    if saved and saved.get("spcs"):   # a saved week keeps its own list and order
        spcs = saved["spcs"] + [s for s in spcs if s not in saved["spcs"] and s in act.index]
    week_no = int(wk.isocalendar()[1])
    sug_spcs = (saved or {}).get("spcs") or list(act.index)
    suggested = roster_suggest(sug_spcs, load, (prev or {}).get("grid"), week_no)
    shifts = R["shifts"].get(store) or DEFAULT_SHIFTS
    return {"stores": stores, "store": store, "scope": [store], "week": wk.strftime("%Y-%m-%d"),
            "week_label": f"{wk.day} {wk:%b} – {days[-1].day} {days[-1]:%b %Y}", "week_no": week_no,
            "days": [{"date": x.strftime("%Y-%m-%d"), "label": f"{x:%a}", "num": x.day, "mon": f"{x:%b}", "tag": day_tags([x]).get(x.strftime("%Y-%m-%d")),
                      "exp_v": round(load[x.weekday()]), "exp_q": round(loadq[x.weekday()], 1),
                      "busy": x.weekday() in set(sorted(range(7), key=lambda i: -load[i])[:2])} for x in days],
            "spcs": [{"name": s, "v": round(float(act.at[s, "v"])) if s in act.index else 0,
                      "q": round(float(act.at[s, "q"])) if s in act.index else 0, "active": s in act.index} for s in spcs],
            "saved": saved, "prev": prev, "suggested": suggested, "shifts": shifts,
            "today": eod_today().strftime("%Y-%m-%d"), "updated": updated_note()}


@app.get("/roster")
def roster_page():
    return page(ROSTER_HTML)


@app.get("/api/roster")
def api_roster():
    return api(lambda st: roster_data(st, request.args))


@app.post("/api/roster")
@admin_api
def api_roster_post():
    body = request.get_json(silent=True) or {}
    st = get_state()
    if st is None:
        return jsonify({"error": "No data available."}), 400
    daily = daily_frame(st)
    stores = sorted(s for s in daily["store"].unique() if s) if daily is not None else []
    store = str(body.get("store", ""))
    wk = parse_date(body.get("week"))
    if store not in stores or wk is None:
        return jsonify({"error": "Not saved: pick a store and a week."}), 400
    wk = monday(wk)
    R = load_roster()
    shifts = body.get("shifts")
    if isinstance(shifts, list) and shifts:
        clean = []
        for s in shifts[:8]:
            code = re.sub(r"[^A-Z0-9]", "", str(s.get("code", "")).upper())[:3]
            if not code:
                continue
            tm = lambda x: x if re.fullmatch(r"\d{2}:\d{2}", str(x or "")) else ""
            clean.append({"code": code, "name": str(s.get("name", code))[:20], "start": tm(s.get("start")), "end": tm(s.get("end")),
                          "color": s.get("color") if re.fullmatch(r"#[0-9a-fA-F]{6}", str(s.get("color", ""))) else "#8e8e93"})
        if clean:
            R["shifts"][store] = clean
    codes = {s["code"] for s in (R["shifts"].get(store) or DEFAULT_SHIFTS)} | {""}
    grid = {}
    for name, row in (body.get("grid") or {}).items():
        name = re.sub(r"\s+", " ", str(name)).strip()[:60]
        if not name or not isinstance(row, list):
            continue
        grid[name] = [str(x).upper() if str(x).upper() in codes else "" for x in (row + [""] * 7)[:7]]
    if body.get("clear"):
        R["weeks"].pop(f"{store}|{wk:%Y-%m-%d}", None)
    else:
        R["weeks"][f"{store}|{wk:%Y-%m-%d}"] = {"grid": grid, "spcs": [s for s in (body.get("spcs") or list(grid)) if s in grid][:40],
                                                "note": str(body.get("note", ""))[:300],
                                                "saved": datetime.now().strftime("%d %b %Y, %I:%M %p")}
    # keep the last 26 weeks per store
    keys = sorted((k for k in R["weeks"] if k.startswith(store + "|")), reverse=True)
    for k in keys[26:]:
        R["weeks"].pop(k, None)
    save_roster(R)
    audit("roster saved", f"{store} · week of {wk:%d %b %Y}")
    return api(lambda st: roster_data(st, {"store": store, "week": wk.strftime("%Y-%m-%d")}))


# ════════════════════════════════════════════════════════════════════
#  REVIEW MEETING: the month in a few clear topics, each with takeaways and links to the data behind it
# ════════════════════════════════════════════════════════════════════
def _g(c, b):
    return (c - b) / b * 100 if b else None


def _gt(x):
    return "–" if x is None else f"{'+' if x >= 0 else ''}{x:.1f}%"


def review_data(st, args):
    daily = daily_frame(st)
    if daily is None or daily.empty:
        return {"error": "This sheet has no usable date column."}
    stores = sorted(s for s in daily["store"].unique() if s)
    sel = pick_scope(args, stores)
    d = scope_rows(daily, sel)
    dmax = daily["day"].max()
    months = sorted(set(daily["day"].dt.strftime("%Y-%m").unique()))
    month = args.get("month") if args.get("month") in months else dmax.strftime("%Y-%m")
    date = min(pd.Timestamp(month + "-01") + pd.offsets.MonthEnd(0), dmax)
    w = ov_window("month", date, dmax)
    s, eff, e = w["s"], w["eff"], w["e"]
    cur, lm, ly = ov_slice(d, s, eff), ov_slice(d, *w["bases"]["prev"]), ov_slice(d, *w["bases"]["ly"])
    days_gone, days_in = int((eff - s).days) + 1, int(e.day)
    left = max(0, days_in - days_gone)
    qs = lambda f: {"v": float(f["v"].sum()), "q": float(f["q"].sum())}
    C, L, Y = qs(cur), qs(lm), qs(ly)
    sel_q = "&".join("store=" + urllib.parse.quote(x) for x in sel)
    amp = ("&" + sel_q) if sel_q else ""
    qlink = lambda path, extra="": path + (("?" + "&".join(x for x in (extra, sel_q) if x)) if (extra or sel_q) else "")
    topics = []

    # 1. headline
    gv, gq, gyv = _g(C["v"], L["v"]), _g(C["q"], L["q"]), _g(C["v"], Y["v"])
    asp, lasp = (C["v"] / C["q"] if C["q"] else 0), (L["v"] / L["q"] if L["q"] else 0)
    tone = "good" if (gv or 0) >= 5 else "bad" if (gv or 0) <= -5 else "warn"
    tk = []
    if gv is not None:
        tk.append(f"Value is {'up' if gv >= 0 else 'down'} <b>{abs(gv):.1f}%</b> on LMTD ({inr_short(C['v'])} vs {inr_short(L['v'])})"
                  + (f" and {'up' if gyv >= 0 else 'down'} {abs(gyv):.1f}% on last year." if gyv is not None else "."))
    if gq is not None and gv is not None and (gq - gv) > 3:
        tk.append(f"Units grew faster than value ({_gt(gq)} vs {_gt(gv)}): ASP slipped to {inr_short(asp)} from {inr_short(lasp)}. Push premium models and attach.")
    elif gq is not None and gv is not None and (gv - gq) > 3:
        tk.append(f"Value grew faster than units: ASP is up to {inr_short(asp)} from {inr_short(lasp)}. Premium mix is working; protect volume.")
    if left:
        tk.append(f"{left} day{'s' if left != 1 else ''} left: at the current pace the month closes near <b>{inr_short(C['v'] / days_gone * days_in)}</b>.")
    topics.append({"id": "headline", "title": "Month at a glance", "tone": tone,
                   "kpis": [{"k": "Value MTD", "v": inr_short(C["v"]), "s": _gt(gv) + " vs LMTD"},
                            {"k": "Units MTD", "v": f"{C['q']:,.0f}", "s": _gt(gq) + " vs LMTD"},
                            {"k": "ASP", "v": inr_short(asp), "s": _gt(_g(asp, lasp)) + " vs LMTD"},
                            {"k": "vs LYSMTD", "v": _gt(gyv), "s": inr_short(Y["v"]) + " last year"}],
                   "takeaways": tk, "links": [{"label": "Overview · Month", "href": qlink("/", "mode=month")},
                                              {"label": "Day-wise sales", "href": qlink("/", "mode=month") + "#daywise"},
                                              {"label": "Period History", "href": qlink("/", "mode=month") + "#periodsBlock"}]})

    # 2. target (SP)
    t = load_targets()
    tgt, _src = scope_target(t, sel, month, stores)
    spc_t = scope_spc_targets(t, sel, month, stores)
    sp = qs(sp_rows(cur))
    if tgt and (tgt.get("v") or tgt.get("q")):
        tv, tq = tgt.get("v") or 0, tgt.get("q") or 0
        ach = sp["v"] / tv * 100 if tv else None
        proj = sp["v"] / days_gone * days_in if days_gone else 0
        tg = days_gone / days_in * 100
        need = max(0.0, tv - sp["v"]) / left if left and tv else 0
        need90 = max(0.0, tv * 0.9 - sp["v"]) / left if left and tv else 0
        tone = "good" if ach is not None and ach >= tg else "bad" if ach is not None and ach < tg * 0.85 else "warn"
        tk = [f"SP achievement is <b>{ach:.1f}%</b> of the value target with {tg:.0f}% of the month gone; projected close <b>{proj / tv * 100:.0f}%</b> ({inr_short(proj)})." if ach is not None else "No SP value target."]
        if left and need:
            tk.append(f"To reach 100% the store needs <b>{inr_short(need)}/day</b> for the last {left} days (90% needs {inr_short(need90)}/day); "
                      f"the current pace is {inr_short(sp['v'] / days_gone)}/day.")
        if tq:
            tk.append(f"Units: {sp['q']:,.0f} of {tq:,.0f} ({sp['q'] / tq * 100:.1f}%).")
        topics.append({"id": "target", "title": "Target vs Achievement · SP", "tone": tone,
                       "kpis": [{"k": "Ach% value", "v": f"{ach:.1f}%" if ach is not None else "–", "s": f"time gone {tg:.0f}%"},
                                {"k": "Projected", "v": inr_short(proj), "s": f"target {inr_short(tv)}"},
                                {"k": "Needed / day", "v": inr_short(need) if left else "–", "s": f"{left} days left"},
                                {"k": "Units", "v": f"{sp['q']:,.0f}", "s": f"of {tq:,.0f}" if tq else "no units target"}],
                       "takeaways": tk, "links": [{"label": "Target vs Achievement", "href": qlink("/targets", f"month={month}")}]})
    else:
        topics.append({"id": "target", "title": "Target vs Achievement · SP", "tone": "warn", "kpis": [],
                       "takeaways": [f"No SP target is set for {pd.Timestamp(month + '-01'):%B %Y}" + (" for this store." if len(sel) == 1 else ".")
                                     + " Set it so the review can show Ach%, required run rate and projection."],
                       "links": [{"label": "Set targets", "href": qlink("/targets", f"month={month}")}]})

    # 3. segments
    seg_c = cur.groupby("seg")[["v", "q"]].sum()
    seg_l = lm.groupby("seg")[["v", "q"]].sum()
    rows = []
    for g in seg_c.index.union(seg_l.index):
        if not g:
            continue
        cv, lv = float(seg_c["v"].get(g, 0)), float(seg_l["v"].get(g, 0))
        rows.append({"name": g, "v": round(cv), "lv": round(lv), "g": _g(cv, lv),
                     "share": cv / C["v"] * 100 if C["v"] else 0, "lshare": lv / L["v"] * 100 if L["v"] else 0})
    rows.sort(key=lambda r: -r["v"])
    tk = []
    downs = sorted([r for r in rows if r["g"] is not None and r["g"] < -5 and r["lv"] > L["v"] * 0.03], key=lambda r: r["v"] - r["lv"])
    ups = sorted([r for r in rows if r["g"] is not None and r["g"] > 5], key=lambda r: -(r["v"] - r["lv"]))
    if ups:
        tk.append("Growing: " + ", ".join(f"<b>{esc_html(r['name'])}</b> {_gt(r['g'])}" for r in ups[:3]) + ".")
    if downs:
        tk.append("Falling: " + ", ".join(f"<b>{esc_html(r['name'])}</b> {_gt(r['g'])} ({inr_short(r['v'] - r['lv'])})" for r in downs[:3])
                  + ". Review stock, offers and SPC focus here.")
    shift = sorted(rows, key=lambda r: -abs(r["share"] - r["lshare"]))
    if shift and abs(shift[0]["share"] - shift[0]["lshare"]) >= 2:
        r = shift[0]
        tk.append(f"Biggest mix shift: {esc_html(r['name'])} {r['lshare']:.1f}% → {r['share']:.1f}% of value.")
    topics.append({"id": "segments", "title": "Segments & mix", "tone": "bad" if downs and not ups else "good" if ups and not downs else "warn",
                   "table": {"head": ["Segment", "MTD", "LMTD", "Growth", "Share"],
                             "rows": [[r["name"], inr_short(r["v"]), inr_short(r["lv"]), _gt(r["g"]), f"{r['share']:.1f}%"] for r in rows[:8]]},
                   "takeaways": tk or ["Segment sales are in line with last month."],
                   "links": [{"label": "Breakdown by segment", "href": qlink("/", "mode=month&dim=seg")},
                             {"label": "Chart: segment by day", "href": "/charts"}]})

    # 4. SPCs
    sc = cur[cur["spc"] != ""].groupby("spc")[["v", "q"]].sum()
    sl = lm[lm["spc"] != ""].groupby("spc")[["v", "q"]].sum()
    tg_frac = days_gone / days_in
    srows = []
    for n in sc.index.union(sl.index):
        cv, lv = float(sc["v"].get(n, 0)), float(sl["v"].get(n, 0))
        spt = (spc_t.get(n) or {}).get("v")
        spv = float(sp_rows(cur[cur["spc"] == n])["v"].sum()) if spt else 0
        srows.append({"name": n, "v": cv, "lv": lv, "g": _g(cv, lv), "d": cv - lv,
                      "ach": spv / spt * 100 if spt else None, "q": float(sc["q"].get(n, 0))})
    srows.sort(key=lambda r: -r["v"])
    tk = []
    if srows:
        top = srows[0]
        tk.append(f"Top performer: <b>{esc_html(top['name'])}</b> with {inr_short(top['v'])} ({top['v'] / C['v'] * 100 if C['v'] else 0:.1f}% of the store), {_gt(top['g'])} on LMTD.")
        drop = sorted([r for r in srows if r["lv"] > 0], key=lambda r: r["d"])
        if drop and drop[0]["d"] < 0:
            r = drop[0]
            tk.append(f"Biggest drop: <b>{esc_html(r['name'])}</b> {inr_short(r['d'])} ({_gt(r['g'])}). Discuss focus models and walk-in conversion.")
        risk = [r for r in srows if r["ach"] is not None and r["ach"] < tg_frac * 100 * 0.8]
        if risk:
            tk.append(f"{len(risk)} SPC{'s are' if len(risk) != 1 else ' is'} behind target pace (under 80% of time gone): "
                      + ", ".join(f"{esc_html(r['name'])} {r['ach']:.0f}%" for r in sorted(risk, key=lambda r: r["ach"])[:4]) + ".")
        if len(srows) > 2 and C["v"]:
            top2 = sum(r["v"] for r in srows[:2]) / C["v"] * 100
            if top2 > 55:
                tk.append(f"Top 2 SPCs bring {top2:.0f}% of the store: the rest of the team needs support to spread the load.")
    topics.append({"id": "spc", "title": "SPC performance", "tone": "warn" if any(r["ach"] is not None and r["ach"] < tg_frac * 80 for r in srows) else "good",
                   "table": {"head": ["SPC", "MTD", "Growth", "Units", "SP Ach%"],
                             "rows": [[r["name"], inr_short(r["v"]), _gt(r["g"]), f"{r['q']:,.0f}", f"{r['ach']:.0f}%" if r["ach"] is not None else "–"] for r in srows[:10]]},
                   "takeaways": tk or ["No SPC sales this month yet."],
                   "links": [{"label": "SPC Performance", "href": qlink("/spc")}, {"label": "SPC targets", "href": qlink("/targets", f"month={month}")},
                             {"label": "Compare SPCs", "href": qlink("/compare", "by=spc")}]})

    # 5. models
    fc = cur.groupby("fam")[["v", "q"]].sum()
    fl = lm.groupby("fam")[["v", "q"]].sum()
    delta = (fc["v"].reindex(fc.index.union(fl.index), fill_value=0) - fl["v"].reindex(fc.index.union(fl.index), fill_value=0)).sort_values()
    delta = delta[[i for i in delta.index if i and i != "Unknown"]]
    gain, lose = delta[delta > 0].sort_values(ascending=False)[:5], delta[delta < 0][:5]
    tk = []
    if len(fc):
        best = fc["v"].sort_values(ascending=False)
        tk.append("Best sellers by value: " + ", ".join(f"<b>{esc_html(i)}</b> {inr_short(float(v))}" for i, v in best[:3].items()) + ".")
    if len(gain):
        tk.append("Gaining most: " + ", ".join(f"{esc_html(i)} +{inr_short(float(v))}" for i, v in gain[:3].items()) + ".")
    if len(lose):
        tk.append("Losing most: " + ", ".join(f"{esc_html(i)} {inr_short(float(v))}" for i, v in lose[:3].items()) + ". Check stock and price first.")
    topics.append({"id": "models", "title": "Models: winners and decliners", "tone": "warn" if len(lose) and (len(gain) == 0 or float(-lose.sum()) > float(gain.sum())) else "good",
                   "table": {"head": ["Model", "Change vs LMTD", "MTD units"],
                             "rows": [[i, ("+" if float(v) >= 0 else "") + inr_short(float(v)), f"{float(fc['q'].get(i, 0)):,.0f}"] for i, v in list(gain.items())[:4] + list(lose.items())[:4]]},
                   "takeaways": tk or ["No model sales this month yet."],
                   "links": [{"label": "Breakdown by product", "href": qlink("/", "mode=month&dim=fam")}, {"label": "Products × SPC", "href": qlink("/spc") + "#prodSpcTable"}]})

    # 6. day pattern
    dd = cur.groupby("day")["v"].sum()
    hist = ov_slice(d, s - pd.Timedelta(days=84), eff).groupby("day")["v"].sum()
    tk = []
    if len(dd):
        avg = float(dd.mean())
        weak = dd[dd < avg * 0.7]
        best_d, worst_d = dd.idxmax(), dd.idxmin()
        tk.append(f"Average day {inr_short(avg)}; best {best_d.day} {best_d:%b} ({best_d:%a}) at {inr_short(float(dd.max()))}, weakest {worst_d.day} {worst_d:%b} ({worst_d:%a}) at {inr_short(float(dd.min()))}.")
        if len(weak):
            tk.append(f"{len(weak)} day{'s were' if len(weak) != 1 else ' was'} under 70% of the average: " + ", ".join(f"{x.day} {x:%b}" for x in weak.index[:6]) + ". Plan activities and staffing for these days.")
        if len(hist) > 14:
            wdm = hist.groupby(hist.index.weekday).mean()
            names = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
            tk.append(f"Over 12 weeks, <b>{names[int(wdm.idxmax())]}</b> is the busiest weekday and <b>{names[int(wdm.idxmin())]}</b> the quietest: put week-offs on quiet days.")
    topics.append({"id": "days", "title": "Day-wise pattern", "tone": "warn" if len(dd) and (dd < dd.mean() * 0.7).sum() > 3 else "good",
                   "spark": [round(float(dd.get(x, 0))) for x in pd.date_range(s, eff)],
                   "spark_tags": [day_tags([x]).get(x.strftime("%Y-%m-%d")) for x in pd.date_range(s, eff)], "takeaways": tk or ["No sales yet."],
                   "links": [{"label": "Day-wise sales", "href": qlink("/", "mode=month") + "#daywise"}, {"label": "Duty roster", "href": qlink("/roster")}]})

    # 7. zero sell-out
    _d2, zc, _zr, zrefm, zcurm, zmodels = zero_core(daily, sel, s, eff, 90, 1)
    sold_now = [f for f in zmodels if zcurm.get(f, 0) > 0]
    zero_models = [f for f in zmodels if zcurm.get(f, 0) <= 0 and zrefm.get(f, 0) >= 3]
    byf = zc[zc["spc"] != ""].groupby(["spc", "fam"])["q"].sum()
    topm = [f for f in zcurm.sort_values(ascending=False).index if f in sold_now][:10]
    gaps = []
    for n in sc.index:
        mine = {f for (sp_, f), q in byf.items() if sp_ == n and q > 0}
        miss = [f for f in topm if f not in mine]
        gaps.append((n, miss))
    gaps.sort(key=lambda x: -len(x[1]))
    tk = []
    if zero_models:
        tk.append(f"<b>{len(zero_models)} model{'s' if len(zero_models) != 1 else ''}</b> that sold earlier (3+ units in the last 90 days) have <b>zero sales</b> this month: "
                  + ", ".join(esc_html(f) for f in sorted(zero_models, key=lambda f: -zrefm.get(f, 0))[:6]) + ".")
    if gaps and gaps[0][1]:
        n, miss = gaps[0]
        tk.append(f"{esc_html(n)} has not sold {len(miss)} of the store's top {len(topm)} models ({', '.join(esc_html(f) for f in miss[:4])}).")
    topics.append({"id": "zero", "title": "Sell-out gaps", "tone": "bad" if len(zero_models) > 3 else "warn" if zero_models or (gaps and len(gaps[0][1]) >= 3) else "good",
                   "takeaways": tk or ["Every model that sold before has sold this month."],
                   "links": [{"label": "Sell-Out Gap Analysis", "href": qlink("/zero", "preset=mtd")}] +
                            ([{"label": f"{gaps[0][0]}'s zero models", "href": qlink("/zero", "preset=mtd&spc=" + urllib.parse.quote(gaps[0][0]))}] if gaps and gaps[0][1] else [])})

    # 8. activations
    fr, _err = activation_frame(st)
    if fr is not None:
        pa = fr[fr["store"].isin(sel)] if sel else fr
        pa = pa[(pa["sale"] >= (s - pd.DateOffset(months=1))) & (pa["sale"] <= eff)]   # this month's and last month's sales
        old = pa[pa["days"] > 3]
        topics.append({"id": "activation", "title": "Pending activations", "tone": "bad" if len(old) > 10 else "warn" if len(old) else "good",
                       "kpis": [{"k": "Pending", "v": f"{len(pa):,}", "s": inr_short(float(pa['v'].sum()))},
                                {"k": "Over 3 days", "v": f"{len(old):,}", "s": f"oldest {int(pa['days'].max()) if len(pa) else 0} days"}],
                       "takeaways": [f"{len(old)} sale{'s have' if len(old) != 1 else ' has'} waited over 3 days for activation; they may not be claimed. Chase them today."] if len(old)
                       else ["No sale is waiting more than 3 days for activation."],
                       "links": [{"label": "Activations & Claims", "href": qlink("/activation")}]})

    # 9. stock
    stk = load_stock()
    st_stores = [x for x in (sel or stores) if x in stk]
    if st_stores:
        outs = crit = 0
        dead = 0.0
        names = []
        for x in st_stores[:6]:
            a = stock_analysis(st, x)
            k = a.get("kpis") or {}
            outs += k.get("out", 0)
            crit += k.get("critical", 0)
            dead += k.get("dead_v", 0)
            names += [r["name"] for r in a.get("models", []) if r["status"] in ("out", "critical")][:3]
        topics.append({"id": "stock", "title": "Stock health", "tone": "bad" if outs else "warn" if crit or dead else "good",
                       "kpis": [{"k": "Out of stock", "v": str(outs), "s": "selling models"}, {"k": "Critical", "v": str(crit), "s": "≤5 days of cover"},
                                {"k": "Dead stock", "v": inr_short(dead), "s": "no sale in 30 days"}],
                       "takeaways": ([f"Refill first: {', '.join(esc_html(n) for n in names[:6])}."] if names else []) +
                                    ([f"{inr_short(dead)} sits in models that have not sold in 30 days: plan a push or a transfer."] if dead else []) or ["Stock is healthy."],
                       "links": [{"label": "Stock & Sell-Out", "href": qlink("/stock")}]})
    # 10. campaigns
    live = [c for c in load_campaigns() if c.get("on", True) and c.get("end", "") >= s.strftime("%Y-%m-%d") and c.get("start", "") <= eff.strftime("%Y-%m-%d")]
    if live:
        b = st.get("boost") or {}
        topics.append({"id": "campaigns", "title": "Campaign multipliers in this month", "tone": "info",
                       "takeaways": [f"<b>{esc_html(c['name'])}</b>: {', '.join(esc_html(m) for m in c['models'][:4])} × {c.get('unit_mult', 1):g} units / × {c.get('value_mult', 1):g} value, "
                                     f"{fmt_range(pd.Timestamp(c['start']), pd.Timestamp(c['end']))} (adds {b.get(c['id'], {}).get('xq', 0):,} units, {inr_short(b.get(c['id'], {}).get('xv', 0))})." for c in live[:5]]
                       + ["Every figure on this page already includes these multipliers."],
                       "links": [{"label": "Campaign Multipliers", "href": "/campaigns"}]})
    order = {"bad": 0, "warn": 1, "info": 2, "good": 3}
    agenda = []
    for tp in sorted(topics, key=lambda t: order.get(t["tone"], 2)):
        if tp["takeaways"]:
            agenda.append({"id": tp["id"], "title": tp["title"], "tone": tp["tone"], "text": tp["takeaways"][0]})
    return {"stores": stores, "scope": sel, "store_label": scope_label(sel), "month": month,
            "months": [{"key": m, "label": f"{pd.Timestamp(m + '-01'):%b %Y}"} for m in months[-12:]],
            "label": f"{s:%B %Y}", "range": fmt_range(s, eff), "days_gone": days_gone, "days_in": days_in,
            "topics": topics, "agenda": agenda[:6], "updated": updated_note(), "amp": amp}


@app.get("/review")
def review_page():
    return page(REVIEW_HTML)


@app.get("/api/review")
def api_review():
    return api(lambda st: review_data(st, request.args))


