def page_context_text(pctx):
    if not isinstance(pctx, dict):
        return ""
    parts = [f"Page: {str(pctx.get('title', ''))[:60]}", f"Stores: {str(pctx.get('store', ''))[:80]}", f"Period: {str(pctx.get('period', ''))[:80]}"]
    if pctx.get("controls"):
        parts.append("Selected: " + ", ".join(str(c)[:30] for c in pctx["controls"][:12]))
    for sec in (pctx.get("sections") or [])[:14]:
        parts.append(f"[{str(sec.get('h', ''))[:60]}] {str(sec.get('t', ''))[:360]}")
    return " | ".join(parts)[:4500]


def section_help(h):
    low = h.lower().strip()
    for pat, txt in SECTION_HELP:
        if re.search(pat, low):
            return txt
    return ""


def _excerpt(t, n=170):
    t = re.sub(r"\s+", " ", str(t or "")).strip()
    return esc_html(t[:n] + ("…" if len(t) > n else ""))


def ask_page_explain(question, page, pctx):
    """Answers about the page on screen: the whole page, one section by name, or what deserves attention."""
    t = (question or "").lower().replace("’", "'").strip()
    secs = [s for s in ((pctx or {}).get("sections") or []) if isinstance(s, dict) and str(s.get("h", "")).strip()][:16]
    name = PAGE_NAMES.get(page, (pctx or {}).get("title") or "this page")
    where = ", ".join(x for x in (str((pctx or {}).get("store", "")).strip(), str((pctx or {}).get("period", "")).strip()) if x)
    # one section by name: 'what is share shift', 'explain the SPC scorecard'
    if secs and re.search(r"\bwhat\b|\bexplain\b|\bmean|\bshow|\bhow (?:do|to) (?:i )?read\b|\btell me about\b", t):
        hit = None
        for sec in sorted(secs, key=lambda s: -len(str(s.get("h")))):
            h = re.sub(r"\s+", " ", str(sec["h"])).strip()
            if len(h) >= 4 and re.search(r"(?<![a-z0-9])" + re.escape(h.lower()) + r"(?![a-z0-9])", t):
                hit = sec
                break
        if hit:
            h = str(hit["h"]).strip()
            how = section_help(h) or "this part of the page."
            return {"text": f"<b>{esc_html(h)}</b> shows {esc_html(how)}",
                    "steps": [f"On your screen now: {_excerpt(hit.get('t'), 260)}"] if hit.get("t") else [],
                    "chips": ["Explain this page", "What should I focus on here?"], "help": True}
    if EXPLAIN_PAGE.search(t) or t in ("explain", "explain this", "what is this"):
        steps = []
        for sec in secs[:9]:
            h = str(sec["h"]).strip()
            how = section_help(h)
            steps.append(f"<b>{esc_html(h)}</b>" + (f": {esc_html(how)}" if how else "") + (f" <span class='muted'>Now: {_excerpt(sec.get('t'), 110)}</span>" if sec.get("t") else ""))
        ctl = [str(c)[:24] for c in ((pctx or {}).get("controls") or [])][:6]
        lead = PAGE_GUIDE.get(page, f"This is {name}.")
        return {"text": f"{esc_html(lead)}" + (f" You're looking at <b>{esc_html(where)}</b>" if where else "")
                        + (f" with {esc_html(', '.join(ctl))} picked." if ctl else "."),
                "steps": steps or ["Scroll down to see each section; tap the share icon by a heading to save or send it."],
                "chips": ["What should I focus on here?"] + [f"What is {str(s['h']).strip()}?" for s in secs[:3]], "help": True}
    if FOCUS_Q.search(t):
        notes = []
        for sec in secs:
            txt = re.sub(r"\s+", " ", str(sec.get("t", "")))
            downs = re.findall(r"([A-Za-z][\w &+./-]{1,40}?)\s*[^\s↓]*\s*↓\s*([\d.]+%)", txt)
            if downs:
                notes.append(f"<b>{esc_html(sec['h'])}</b>: down on {esc_html(downs[0][0].strip())} ({esc_html(downs[0][1])})"
                             + (f" and {len(downs) - 1} more" if len(downs) > 1 else ""))
            for kw, msg in (("out of stock", "models out of stock"), ("critical", "models about to run out"), ("behind", "behind target pace"),
                            ("at risk", "at risk"), ("zero", "zero sales")):
                if kw in txt.lower() and len(notes) < 8 and not any(msg in n for n in notes):
                    notes.append(f"<b>{esc_html(sec['h'])}</b>: {msg} ({_excerpt(txt[max(0, txt.lower().find(kw) - 60):txt.lower().find(kw) + 80], 140)})")
        return {"text": f"On <b>{esc_html(name)}</b>" + (f" ({esc_html(where)})" if where else "") + ", these deserve a look first:" if notes
                else f"Nothing on <b>{esc_html(name)}</b> is falling against its comparison right now.",
                "steps": notes[:6] or ["Every section on screen is level or growing. Switch the base pill (vs Previous / vs Last Year) to check against last year too."],
                "chips": ["Explain this page"], "help": True}
    return None


